use anyhow::Result;
use heiwa_paths::RuntimePaths;
use std::fs;
use std::path::Path;

pub fn write_projections(paths: &RuntimePaths) -> Result<()> {
    write_projection(
        &paths.root().join("generated/codex/config.toml"),
        concat!(
            "# Generated by Heiwa runtime.\n",
            "[heiwa]\n",
            "mode = \"concise\"\n",
            "provider_auth_owner = \"provider\"\n",
            "provider_inference_owner = \"provider\"\n",
            "session_owner = \"heiwa\"\n",
            "sandbox_owner = \"heiwa\"\n",
        ),
    )?;
    write_projection(
        &paths.root().join("generated/claude/settings.json"),
        concat!(
            "{\n",
            "  \"mode\": \"concise\",\n",
            "  \"providerAuthOwner\": \"provider\",\n",
            "  \"providerInferenceOwner\": \"provider\",\n",
            "  \"sessionOwner\": \"heiwa\",\n",
            "  \"sandboxOwner\": \"heiwa\"\n",
            "}\n"
        ),
    )?;
    write_projection(
        &paths.root().join("generated/gemini/settings.json"),
        concat!(
            "{\n",
            "  \"mode\": \"concise\",\n",
            "  \"providerAuthOwner\": \"provider\",\n",
            "  \"providerInferenceOwner\": \"provider\",\n",
            "  \"sessionOwner\": \"heiwa\",\n",
            "  \"sandboxOwner\": \"heiwa\"\n",
            "}\n"
        ),
    )?;
    write_projection(
        &paths.root().join("generated/antigravity/settings.json"),
        concat!(
            "{\n",
            "  \"mode\": \"concise\",\n",
            "  \"inherits\": \"gemini\",\n",
            "  \"providerAuthOwner\": \"provider\",\n",
            "  \"providerInferenceOwner\": \"provider\",\n",
            "  \"sessionOwner\": \"heiwa\",\n",
            "  \"sandboxOwner\": \"heiwa\"\n",
            "}\n"
        ),
    )?;
    write_projection(
        &paths.root().join("generated/codex/AGENTS.md"),
        &generated_context("Codex", "codex"),
    )?;
    write_projection(
        &paths.root().join("generated/claude/CLAUDE.md"),
        &generated_context("Claude Code", "claude"),
    )?;
    write_projection(
        &paths.root().join("generated/gemini/GEMINI.md"),
        &generated_context("Gemini CLI", "gemini"),
    )?;
    write_projection(
        &paths.root().join("generated/antigravity/GEMINI.md"),
        &generated_context("Antigravity", "antigravity"),
    )?;
    write_projection(
        &paths.root().join("generated/ollama/SYSTEM.md"),
        &generated_context("Ollama via Heiwa", "ollama"),
    )?;
    Ok(())
}

fn write_projection(path: &Path, content: &str) -> Result<()> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
    }
    fs::write(path, content)?;
    Ok(())
}

fn generated_context(surface_name: &str, surface_id: &str) -> String {
    format!(
        concat!(
            "# Heiwa Concise Context\n\n",
            "Generated by Heiwa runtime for {surface_name} (`{surface_id}`).\n\n",
            "Apply this by default:\n\n",
            "- smallest sufficient answer\n",
            "- lead with result, action, or blocker\n",
            "- no filler, cheerleading, or repeated framing\n",
            "- keep commands, paths, dates, risks, and errors exact\n",
            "- interim updates: 1-2 short lines max\n",
            "- if user asks for Caveman, compress harder without losing technical truth\n",
            "- if user asks for normal or deep output, leave concise mode\n",
            "- use normal clarity for destructive actions, security warnings, or ambiguity\n",
            "- providers own auth and inference internals\n",
            "- Heiwa owns sessions and sandboxes\n"
        ),
        surface_name = surface_name,
        surface_id = surface_id,
    )
}
